-- ترحيل 137 — «هل بيانات هذا الكيان تجريبية؟» تصير حقيقةً مسجَّلة، بعد أن كانت تُستنتج من اسم الكيان.
--
-- كان اسم الكيان «3,6T — بيئة تجريبية» يحمل معنيين لا علاقة لأحدهما بالآخر:
--   (1) تحذيرٌ يُطبع في ذيل كل خطاب وقسيمة راتب ومستند إنتاج وتقرير عميل: «أُنتجت من منصة 3,6T — بيئة
--       تجريبية ببيانات مصطنعة». وهو في الواقع نصٌّ مكتوب بحرفه في أربعة ملفات ولا يقرأ اسم الكيان أصلًا،
--       فيُطبع سواء أكانت البيانات تجريبية أم لا.
--   (2) حارسٌ في installServiceCatalog يرفض العمل ما لم يطابق الاسمُ هذه العبارة بالحرف. فصار اسم العرض
--       اعتماديةً صلبة: تغييره إلى «3,6T» يُعطِّل مثبِّت الدليل.
-- والنتيجة أن المالك لا يستطيع أن يسمّي شركته باسمها دون كسر المثبِّت، وأن مستنداته الرسمية تقول عن نفسها
-- إنها تجريبية بعد أن تصير حقيقية.
--
-- فيُفصل المعنيان: `demo_data` حقيقةٌ يقرّرها المالك، والاسم اسمٌ للعرض وحده.
--   demo_data=1  البيانات ما زالت تجريبية: التحذير يُطبع، والمثبِّت يعمل (وهو يعيد كتابة الدليل كله فلا يُشغَّل على بيانات حقيقية).
--   demo_data=0  المالك أقرّ أن البيانات صارت بيانات الشركة: التحذير يسقط، والمثبِّت يرفض العمل.
-- الافتراض 1 عمدًا: الكيان القائم اليوم بياناته تجريبية فعلًا (22 حسابًا من 28 موسوم «تجريبي»)، والانتقال
-- إلى 0 قرارٌ يتخذه المالك بعد أن يصير الناس الحقيقيون على المنصة، لا أثرٌ جانبي لترحيل.
ALTER TABLE tenants ADD COLUMN demo_data INTEGER NOT NULL DEFAULT 1;

-- القيمة الوحيدة المقبولة صفر أو واحد. STRICT يضمن النوع لا المدى.
CREATE TRIGGER tenants_demo_flag_binary BEFORE UPDATE OF demo_data ON tenants
BEGIN
  SELECT CASE WHEN NEW.demo_data NOT IN (0,1)
    THEN RAISE(ABORT,'demo_data تكون 0 أو 1') END;
END;
